import {applications} from './workloads.js';
import {publicationPaths} from './kernel-path.js';
import {packetDetailsHTML} from './packet-fields.js';
const esc=s=>String(s??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function logicalTopology(s,appId){
 const p=s.nodes.flatMap(host=>publicationPaths(s,host)).find(p=>p.id===appId);if(!p)return null;const host=p.host,app=p.app||{...p.entity,interfaces:[]};
 const guestLink=s.links.find(l=>l.a===p.ingress?.id||l.b===p.ingress?.id),vmPortId=guestLink&&(guestLink.a===p.ingress.id?guestLink.b:guestLink.a),vm=s.nodes.find(n=>n.interfaces.some(p=>p.id===vmPortId));
 const vmPort=vm?.interfaces.find(p=>p.id===vmPortId),vmbr=s.nodes.find(n=>n.type==='bridge'&&n.members?.includes(vmPortId));
 const physical=s.nodes.flatMap(n=>n.interfaces.map(p=>({n,p}))).find(({p})=>p.kind==='physical'&&vmbr?.members?.includes(p.id));
 const vethLink=s.links.find(l=>l.a===p.destination?.id||l.b===p.destination?.id),vethId=vethLink&&(vethLink.a===p.destination.id?vethLink.b:vethLink.a),veth=(p.backendHost||host).interfaces.find(p=>p.id===vethId);
 const process=applications(s,app).find(n=>n.services.http?.port===p.service.port);
 const steps=[
  {key:'physical',title:physical?`${physical.p.name} · физический NIC`:'Физический NIC не связан с мостом',owner:physical?.n.name,detail:'Получает Ethernet-кадр из внешней сети.',ports:[physical?.p.id],nodes:[physical?.n.id],kind:'physical',next:'участник моста · внутренняя привязка'},
  {key:'proxmox',title:vmbr?.name||'Мост Proxmox не подключён',owner:'Сетевое ядро Proxmox',detail:'L2: передаёт кадр к виртуальному адаптеру ВМ. IP пакета не меняется.',ports:vmbr?.interfaces.map(p=>p.id)||[],nodes:[vmbr?.id],kind:'bridge',next:'виртуальный адаптер ВМ'},
  {key:'guest',title:`${vmPort?.name||'vNIC не связан'} ≡ ${p.ingress?.name||'интерфейс Ubuntu не задан'}`,owner:`${vm?.name||'ВМ'} / ${host.name}`,detail:`Один адаптер в двух представлениях. IP ${p.ingress?.ip||'не задан'} назначен внутри Ubuntu.`,ports:[vmPortId,p.ingress?.id],nodes:[vm?.id],kind:'virtual',next:'пакет поступает в сетевой стек Ubuntu'},
  {key:'kernel',title:p.kind==='kubernetes'?'Kubernetes Service → NodePort → DNAT':'Ядро Ubuntu · DNAT → маршрутизация',owner:p.kind==='kubernetes'?`kube-proxy + conntrack · externalTrafficPolicy ${p.policy||'Local'}`:'L3 + conntrack · правило публикации Docker',detail:`${p.ingress?.ip||'?'}:${p.service.publishPort} → ${p.destination?.ip||'?'}:${p.service.port}. Меняется назначение; затем выбирается маршрут к Pod (локальный мост или соседний Node).`,ports:[],nodes:[],kind:'nat',next:'FORWARD · внутренний переход, кабель не нужен'},
  {key:'bridge',title:p.bridge?.name||'Linux-мост не подключён',owner:`Linux-мост ядра ${(p.backendHost||host).name}`,detail:`Интерфейс моста: ${p.backendEgress?.ip||p.egress?.ip||'нет IP'}. Это шлюз контейнерной подсети, а не новый адрес назначения запроса.`,ports:p.bridge?.interfaces.map(p=>p.id)||[],nodes:[p.bridge?.id],kind:'bridge',next:'veth хоста присоединён к мосту'},
  {key:'veth',title:`${veth?.name||'veth хоста не найден'} ↔ ${p.destination?.name||'eth0 контейнера'}`,owner:'Одна veth-пара · два конца',detail:'Хостовый конец находится в Ubuntu; второй — в сетевом namespace контейнера (для Kubernetes — общем namespace Pod). У хостового конца обычно нет IP.',ports:[vethId],nodes:[],kind:'virtual',next:'кадр приходит на интерфейс контейнера'},
  {key:'app',title:app.name,owner:p.kind==='kubernetes'?'Pod · общий сетевой namespace':'Контейнер · сетевой namespace',detail:`${p.destination?.ip||'нет IP'}:${p.service.port}. Передаёт запрос процессу приложения в этом namespace.`,ports:[p.destination?.id],nodes:[app.id],kind:'app'}
 ];
 if(p.policy==='Cluster'){const backend=p.backendHost,external=backend?.interfaces.find(p=>p.ip);steps.splice(4,0,{key:'snat',title:'MASQUERADE / SNAT',owner:'Ядро входного worker',detail:'Источник клиента → '+(p.egress?.ip||'?')+'; ответ обязан вернуться на входной Node. Conntrack отменяет оба преобразования на ответе.',ports:[],nodes:[],kind:'nat',next:p.remote?'маршрут к подсети Pod через Node IP другого worker':'локальный маршрут к Pod'});if(p.remote)steps.splice(5,0,{key:'underlay',title:host.name+' → '+backend.name,owner:'Routed CNI · физическая LAN',detail:'eth0 → virtio → vmbr0 → физический NIC → SW-LAN → физический NIC другого сервера → vmbr0 → virtio → eth0 '+(external?.ip||'?')+'. Подсети Pod связаны явным маршрутом via Node IP; туннеля VXLAN здесь нет.',ports:[external?.id],nodes:[backend.id],kind:'physical',next:'ядро удалённой Ubuntu: eth0 → cni0 (L3, не кабель)'});}
 if(p.kind==='kubernetes'){const client=s.nodes.find(n=>n.type==='client'),sw=s.nodes.find(n=>n.type==='switch');steps.unshift({key:'client',title:client?.name||'Клиент',owner:'Браузер / HTTP-клиент',detail:'DNS site.lab → '+(p.ingress?.ip||'?')+'; запрос TCP/'+p.service.publishPort,ports:client?.interfaces.map(p=>p.id)||[],nodes:[client?.id],kind:'physical',next:'медный Ethernet-кабель'},{key:'switch',title:sw?.name||'Коммутатор LAN',owner:'L2 · VLAN',detail:'Передаёт кадр к физическому интерфейсу сервера, где работает выбранный worker.',ports:sw?.interfaces.map(p=>p.id)||[],nodes:[sw?.id],kind:'bridge',next:'кабель к серверу'});if(process){const c=s.nodes.find(n=>n.id===process.parent);steps.at(-1).next='Общий namespace Pod · без дополнительного NIC';steps.push({key:'container',title:c.name,owner:'Контейнер Pod · '+c.services.runtime.image,detail:'Использует eth0 и IP Pod. Отдельного сетевого линка между Pod и контейнером нет.',ports:[],nodes:[c.id],kind:'app'})}}
 if(process){steps.at(-1).next='TCP-сокет внутри namespace · без кабеля';steps.push({key:'process',title:process.name,owner:'Приложение',detail:'HTTP-сервер слушает TCP/'+process.services.http.port+' и формирует ответ. Использует интерфейсы своей среды выполнения.',ports:[],nodes:[process.id],kind:'app'})}
 return{p,steps,ready:p.ready&&!!(vmPort&&vmbr&&physical&&veth)};
}
export function logicalActiveStep(model,event){if(!event)return null;if(event.kernelPathId===model.p.id)return event.kernelPhase==='snat'?'snat':'kernel';if(event.type==='service'&&model.steps.find(step=>step.key==='process'&&step.nodes.includes(event.nodeId)))return'process';if(event.type==='service'&&event.nodeId===model.p.app.id)return'app';if(event.linkIds?.length&&model.p.app?.interfaces.some(p=>p.id===event.toPort||p.id===event.fromPort)&&event.label?.includes('veth'))return'veth';const port=event.toPort||event.portIds?.at(-1);return model.steps.find(step=>step.ports.includes(port))?.key||model.steps.find(step=>step.nodes.includes(event.nodeId))?.key||null}
export class LogicalNetworkView{
 constructor(getState,canvas,player){this.getState=getState;this.canvas=canvas;this.player=player;this.dialog=document.getElementById('logical-network');document.getElementById('logical-topology').onclick=()=>{this.dialog.showModal();this.render()};document.getElementById('logical-close').onclick=()=>this.dialog.close();document.getElementById('logical-app').onchange=()=>this.render();document.getElementById('logical-prev').onclick=()=>player.seek(player.cursor-1);document.getElementById('logical-next').onclick=()=>player.seek(player.cursor+1);document.getElementById('logical-play').onclick=()=>{player.playing?player.pause():player.play();this.update(canvas.trafficView)};document.getElementById('logical-run').onclick=()=>{if(!this.model)return;const s=this.getState(),p=this.model.p,client=s.nodes.find(n=>n.type==='client');if(client)document.getElementById('source').value=client.id;document.getElementById('target').value=p.ingress?.ip||'';document.getElementById('protocol').value='tcp';document.getElementById('port').value=p.service.publishPort;document.getElementById('run').click();this.update(canvas.trafficView)};document.getElementById('logical-fields').onclick=()=>document.getElementById('packet-fields').click()}
 render(){if(!this.dialog.open)return;const s=this.getState(),select=document.getElementById('logical-app'),value=select.value;select.innerHTML=s.nodes.flatMap(host=>publicationPaths(s,host)).sort((a,b)=>Number(b.ready)-Number(a.ready)).map(p=>`<option value="${esc(p.id)}">${esc(p.kind==='kubernetes'?p.entity.name+' / '+p.host.name:p.app.name)}</option>`).join('');if([...select.options].some(o=>o.value===value))select.value=value;const pathId=this.player.result?.trace.find(e=>e.kernelPathId)?.kernelPathId;if(pathId&&this.lastRequest!==this.player.request&&[...select.options].some(o=>o.value===pathId))select.value=pathId;this.lastRequest=this.player.request;this.model=logicalTopology(s,select.value);const chain=document.getElementById('logical-chain');if(!this.model){chain.innerHTML='<p>Сначала настройте контейнер с опубликованным HTTP-портом.</p>';return}chain.innerHTML=this.model.steps.map((step,i)=>`<li data-logical-step="${step.key}" class="logical-${step.kind}"><span class="logical-number">${i+1}</span><div><small>${esc(step.owner)}</small><b>${esc(step.title)}</b><p>${esc(step.detail)}</p></div>${step.next?`<span class="logical-transition">↓ ${esc(step.next)}</span>`:''}</li>`).join('');document.getElementById('logical-health').textContent=this.model.ready?'Связи найдены в текущей схеме':'В цепочке есть отсутствующие связи — проверьте помеченные интерфейсы';this.update(this.canvas.trafficView)}
 update(view){if(!this.dialog.open||!this.model)return;const e=view?.event,key=logicalActiveStep(this.model,e);this.dialog.querySelectorAll('[data-logical-step]').forEach(el=>el.classList.toggle('logical-current',el.dataset.logicalStep===key));document.getElementById('logical-event').textContent=e?e.label:'Запустите «Проверку сети», чтобы видеть пакет в этой цепочке.';document.getElementById('logical-packet').hidden=!this.player.showPacketDetails;document.getElementById('logical-packet').innerHTML=e?packetDetailsHTML(e):'';document.getElementById('logical-fields').textContent='IP/порты: '+(this.player.showPacketDetails?'вкл':'выкл');document.getElementById('logical-fields').setAttribute('aria-pressed',String(this.player.showPacketDetails));document.getElementById('logical-prev').disabled=!e||this.player.cursor===0;document.getElementById('logical-next').disabled=!e||this.player.cursor>=this.player.result.trace.length-1;document.getElementById('logical-play').disabled=!e;document.getElementById('logical-play').textContent=this.player.playing?'Ⅱ Пауза':'▶ Продолжить';document.getElementById('logical-position').textContent=e?`${this.player.cursor+1} / ${this.player.result.trace.length} · ${e.stage}`:'Трасса не запущена'}
}
